server.createContext("/refunds", ex -> {
    var cert = (X509Certificate) ((HttpsExchange) ex).getSSLSession().getPeerCertificates()[0];
    String caller = spiffeId(cert);
    boolean ok = !checkIdentity || Set.of("spiffe://shop.local/ns/prod/sa/orders").contains(caller);
    byte[] body = ((ok ? "refund created for " : "forbidden: ") + caller).getBytes(UTF_8);
    ex.sendResponseHeaders(ok ? 201 : 403, body.length);
    ex.getResponseBody().write(body);
    ex.close();
});
